  const imageFailure = (result) => ({
    disabled: "当前未开启生图",
    unavailable: "当前图片功能不可用",
    busy: "头像正在处理中，请稍候",
    "invalid-target": "主角标识为空或重复，无法确定头像归属",
    "invalid-input": "图片或头像配置无效",
    stale: "人物或页面已变化，本次未替换头像",
