        const result = await imageApi[action](AVATAR_CANVAS, row, file);
        if (!stillCurrent(key, revision)) return;
        if (!result?.ok) {
          showToast(imageFailure(result));
          return;
        }
        if (action !== "deleteImage" && !result.imagePath) {
          showToast("没有收到有效图片，已保留原图");
          return;
